import Image from "next/image";
import Link from "next/link";
import { Post } from "@/types/blog";

const FALLBACK_THUMBNAIL = "https://picsum.photos/seed/tistory/84/84";

interface RankedPostListProps {
  posts: Post[];
}

export default function RankedPostList({ posts }: RankedPostListProps) {
  return (
    <ol className="ranked-list">
      {posts.map((post, index) => (
        <li key={post.id} className="ranked-item">
          <span className="ranked-number">{index + 1}</span>
          <div className="ranked-body">
            <p className="ranked-eyebrow">{post.author}</p>
            <Link href={`/posts/${post.slug}`} className="ranked-title">
              {post.title}
            </Link>
          </div>
          <Link href={`/posts/${post.slug}`} className="ranked-thumb">
            <Image
              src={post.thumbnail ?? FALLBACK_THUMBNAIL}
              alt={post.title}
              fill
              sizes="84px"
            />
          </Link>
        </li>
      ))}
    </ol>
  );
}